return [
  {
    "type": "bar",
    "data": {
      "labels": [$input.first().json.adsetNameValue[0].adsetName1,$input.first().json.adsetNameValue[0].adsetName2],
      "datasets": [
        {
          "type": "bar",
          "label": $input.first().json.impressionsKey,
          "borderColor": "rgb(54, 162, 235)",
          "borderWidth": 2,
          "fill": false,
          "data": $input.first().json.impressionsValue
        },
        {
          "type": "bar",
          "label": $input.first().json.reachKey,
          "backgroundColor": "rgb(255, 99, 132)",
          "data": $input.first().json.reachValue,
          "borderColor": "white",
          "borderWidth": 2
        },
        {
          "type": "bar",
          "label": $input.first().json.clicksKey,
          "backgroundColor": "rgb(75, 192, 192)",
          "data": $input.first().json.clicksValue,
          "borderColor": "white",
          "borderWidth": 2
        }         
      ]
    },   
    "options": {
      "responsive": true,
      "title": {
        "display": true,
        "text": "ADSET LEVEL " + $input.first().json.impressionsKey.toUpperCase() + " - " + $input.first().json.reachKey.toLocaleUpperCase() + " - " + $input.first().json.clicksKey.toLocaleUpperCase() + " COMPARISON CHART"
      },
      "tooltips": {
        "mode": "index",
        "intersect": true
      }
    }
  }
];

const plot = JSON.stringify($input.first().json);

return {
  plot: Buffer.from(plot).toString('base64')
};

